```rust
wit_bindgen::generate!({
    path: "wit",
    world: "node",
    generate_all,
});

use crate::aap::caps::state_read;

struct Node;

/// Keys tried, in order, in the 'subscriptions' store.
const KEYS: [&str; 3] = ["urls", "subscriptions", "list"];

impl Guest for Node {
    fn run(_info: RunInfo) -> SubscriptionList {
        let mut urls: Vec<String> = Vec::new();
        for key in KEYS {
            if let Some(raw) = state_read::get(key) {
                let parsed = parse_urls(&raw);
                if !parsed.is_empty() {
                    urls = parsed;
                    break;
                }
            }
        }
        SubscriptionList { urls }
    }
}

fn parse_urls(raw: &str) -> Vec<String> {
    let trimmed = raw.trim();
    let candidates: Vec<String> = if trimmed.starts_with('[') {
        parse_json_string_array(trimmed).unwrap_or_default()
    } else {
        trimmed
            .split(|c| c == '\n' || c == '\r' || c == ',')
            .map(|s| s.trim().to_string())
            .collect()
    };

    let mut out: Vec<String> = Vec::new();
    for c in candidates {
        let c = c.trim();
        if c.is_empty() || c.starts_with('#') {
            continue;
        }
        if !out.iter().any(|u| u == c) {
            out.push(c.to_string());
        }
    }
    out
}

/// Minimal parser for a JSON array of strings, e.g. `["a", "b"]`.
fn parse_json_string_array(s: &str) -> Option<Vec<String>> {
    let mut chars = s.chars().peekable();
    let mut out = Vec::new();

    skip_ws(&mut chars);
    if chars.next()? != '[' {
        return None;
    }
    skip_ws(&mut chars);
    if chars.peek() == Some(&']') {
        chars.next();
        return Some(out);
    }
    loop {
        skip_ws(&mut chars);
        if chars.next()? != '"' {
            return None;
        }
        let mut cur = String::new();
        loop {
            match chars.next()? {
                '"' => break,
                '\\' => match chars.next()? {
                    '"' => cur.push('"'),
                    '\\' => cur.push('\\'),
                    '/' => cur.push('/'),
                    'n' => cur.push('\n'),
                    't' => cur.push('\t'),
                    'r' => cur.push('\r'),
                    'b' => cur.push('\u{8}'),
                    'f' => cur.push('\u{c}'),
                    'u' => {
                        let mut code = 0u32;
                        for _ in 0..4 {
                            code = code * 16 + chars.next()?.to_digit(16)?;
                        }
                        cur.push(char::from_u32(code).unwrap_or('\u{fffd}'));
                    }
                    _ => return None,
                },
                c => cur.push(c),
            }
        }
        out.push(cur);
        skip_ws(&mut chars);
        match chars.next()? {
            ',' => continue,
            ']' => break,
            _ => return None,
        }
    }
    Some(out)
}

fn skip_ws<I: Iterator<Item = char>>(chars: &mut core::iter::Peekable<I>) {
    while let Some(c) = chars.peek() {
        if c.is_whitespace() {
            chars.next();
        } else {
            break;
        }
    }
}

export!(Node);
